create or replace function public.is_restaurant_staff(p_restaurant_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.restaurant_staff s
    where s.restaurant_id = p_restaurant_id
      and s.user_id = auth.uid()
  );
$$;

create or replace function public.is_reservation_future(p_reserved_for timestamptz)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select p_reserved_for > now();
$$;

create or replace function public.can_read_reservation(p_reservation_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.reservations r
    where r.id = p_reservation_id
      and (
        r.user_id = auth.uid()
        or public.is_restaurant_staff(r.restaurant_id)
      )
  );
$$;

