on public.reservations
for update
to authenticated
using (
  public.is_restaurant_staff(restaurant_id)
  and status = 'booked'
  and not public.is_reservation_future(reserved_for)
)
with check (
  public.is_restaurant_staff(restaurant_id)
  and status in ('seated', 'no_show')
);

