as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if current_user = 'service_role' or coalesce(auth.jwt() ->> 'role', '') = 'service_role' then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if new.invited_by is distinct from auth.uid() then
      raise exception 'invited_by must be the current user';
    end if;
    if new.accepted_at is not null then
      raise exception 'new invites must not be accepted';
    end if;
    if new.expires_at <= now() then
      raise exception 'invite must expire in the future';
    end if;
  elsif tg_op = 'UPDATE' then
    if new.org_id is distinct from old.org_id
       or new.email is distinct from old.email
       or new.role is distinct from old.role then
      raise exception 'only accepted_at can be updated';
    end if;
    if old.accepted_at is not null and new.accepted_at is null then
      raise exception 'cannot unaccept an invite';
    end if;
  end if;

  return new;
end;
$$;

