create or replace function public.issues_before_update()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.project_id is distinct from old.project_id then
    raise exception 'issue id and project_id cannot be changed';
  end if;

  if new.reporter_id is distinct from old.reporter_id then
    raise exception 'reporter_id cannot be changed';
  end if;

  if old.status = 'closed' then
    raise exception 'closed issues cannot be updated';
  end if;

  if new.status not in ('open', 'in_progress', 'closed') then
    raise exception 'invalid status';
  end if;

  if new.is_confidential is distinct from old.is_confidential then
    if old.is_confidential = false then
      if new.is_confidential = true
         and not exists (
           select 1
           from public.project_members m
           where m.project_id = old.project_id
             and m.user_id = auth.uid()
             and m.role = 'maintainer'
         ) then
        raise exception 'only maintainers can make an issue confidential';
      end if;
    else
      if new.is_confidential = false
         and not exists (
           select 1
           from public.project_members m
           where m.project_id = old.project_id
             and m.user_id = auth.uid()
             and m.role = 'maintainer'
         ) then
        raise exception 'only maintainers can unconfidential an issue';
      end if;
    end if;
  end if;

  return new;
end;
$$;

