    from public.prescriptions p
    where p.id = p_prescription_id
      and (p.patient_id = auth.uid() or public.is_pharmacist())
  );
$$;

create or replace function public.can_dispense_prescription(p_prescription_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from public.prescriptions p
    where p.id = p_prescription_id
      and p.refills_left > 0
      and p.expires_at > now()
      and public.is_pharmacist()
      and p.pharmacist_id <> auth.uid()
  );
$$;

create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_refills integer;
begin
  if v_uid is null or not exists (
    select 1
    from public.pharmacists
    where user_id = v_uid
  ) then
    raise exception 'only pharmacists can dispense';
  end if;

  if p_prescription_id is null
     or not exists (
       select 1
       from public.prescriptions p
       where p.id = p_prescription_id
     ) then
    raise exception 'unknown prescription';
  end if;

  perform 1
  from public.prescriptions p
  where p.id = p_prescription_id
    for update;

  if not found then
    raise exception 'prescription not found';
  end if;

  update public.prescriptions
  set refills_left = refills_left - 1
  where id = p_prescription_id
    and refills_left > 0
    and expires_at > now()
    and public.is_pharmacist()
    and pharmacist_id <> v_uid
  returning refills_left into v_refills;

  if not found then
    raise exception 'cannot dispense';
  end if;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_uid);

  return v_refills;
end;
$$;

