create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_prescription public.prescriptions%rowtype;
  v_caller_is_pharmacist boolean;
  v_patient_is_caller boolean;
  v_refills_left integer;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select
    p.*,
    (select exists (select 1 from public.pharmacists where user_id = auth.uid())),
    (select exists (select 1 from public.prescriptions where id = p.id and patient_id = auth.uid()))
  into
    v_prescription,
    v_caller_is_pharmacist,
    v_patient_is_caller
  from public.prescriptions p
  where p.id = p_prescription_id
  for update;

  if not found then
    raise exception 'Prescription not found';
  end if;

  if not v_caller_is_pharmacist then
    raise exception 'Caller is not a pharmacist';
  end if;

  if v_patient_is_caller then
    raise exception 'Cannot dispense own prescription';
  end if;

  if v_prescription.expires_at < now() then
    raise exception 'Prescription has expired';
  end if;

  if v_prescription.refills_left <= 0 then
    raise exception 'No refills left';
  end if;

  update public.prescriptions
  set refills_left = v_prescription.refills_left - 1
  where id = p_prescription_id
  returning refills_left into v_refills_left;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, auth.uid());

  return v_refills_left;
end;
$$;

