create or replace function public.dispense(p_prescription_id bigint)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_refills integer;
  v_ok   boolean := v_uid is not null and public.is_pharmacist();
begin
  if not v_ok then
    raise exception 'dispense: not a pharmacist';
  end if;

  select p.refills_left, p.expires_at
    into v_refills, v_ok
    from public.prescriptions p
   where p.id = p_prescription_id
   for update;

  if not found then
    raise exception 'dispense: unknown prescription';
  end if;

  if v_ok then
    raise exception 'dispense: caller cannot dispense own prescription';
  end if;

  if v_refills <= 0 then
    raise exception 'dispense: no refills left';
  end if;

  if now() > v_ok then
    raise exception 'dispense: prescription has expired';
  end if;

  update public.prescriptions
     set refills_left = refills_left - 1
   where id = p_prescription_id;

  insert into public.dispenses (prescription_id, pharmacist_id)
  values (p_prescription_id, v_uid);

  return v_refills - 1;
end;
$$;

