  if new.prescription_id is null then
    raise exception 'dispense: prescription_id is required';
  end if;

  if new.pharmacist_id is null then
    raise exception 'dispense: pharmacist_id is required';
  end if;

  perform public.dispense(new.prescription_id);
  return new;
end;
$$;

