returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;

  if new.id is distinct from old.id
     or new.project_id is distinct from old.project_id
     or new.lang is distinct from old.lang
     or new.source_text is distinct from old.source_text then
    raise exception 'only target_text and status may be changed';
  end if;

  if new.status = 'reviewed' and old.status = 'draft' then
    if not public.is_reviewer(new.project_id, new.lang) then
      raise exception 'only reviewers can mark segments reviewed';
    end if;
  elsif new.status = 'draft' and old.status = 'draft' then
    if not public.is_assigned(new.project_id, new.lang) then
      raise exception 'not assigned to this language';
    end if;
    if new.translated_by is distinct from old.translated_by then
      if new.translated_by is null or new.translated_by is distinct from auth.uid() then
        raise exception 'translator must record themselves';
      end if;
    end if;
  else
    raise exception 'invalid status transition';
  end if;

  new.translated_by := coalesce(new.translated_by, auth.uid());
  return new;
end;
$$;

