create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_envelope_status text;
  v_signed_at timestamptz := now();
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status
    into v_envelope_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope_status <> 'sent' then
    raise exception 'envelope is not open for signing';
  end if;

  if exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.user_id = v_uid
  ) then
    raise exception 'already signed';
  end if;

  if not exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
     order by r.sign_order
     limit 1
       offset (select r2.sign_order
                 from public.envelope_recipients r2
                where r2.envelope_id = p_envelope_id
                  and r2.sign_order < r.sign_order)
     where r2.signed_at is null
  ) then
    raise exception 'an earlier recipient has not signed yet';
  end if;

  insert into public.envelope_recipients (envelope_id, user_id, sign_order, signed_at)
  values (p_envelope_id, v_uid, (select r.sign_order
                                   from public.envelope_recipients r
                                  where r.envelope_id = p_envelope_id
                                    and r.user_id = v_uid),
         v_signed_at);

  select e.status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id;

  if not exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.signed_at is null
  ) then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;

    v_status := 'completed';
  end if;

  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_envelope_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status
    into v_envelope_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'envelope not found';
  end if;

  if v_envelope_status <> 'sent' then
    raise exception 'envelope is not open for voiding';
  end if;

  if not exists (
    select 1
      from public.envelopes e
     where e.id = p_envelope_id
       and e.sender_id = v_uid
  ) then
    raise exception 'only the sender can void this envelope';
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id;

  select e.status
    into v_status
    from public.envelopes e
   where e.id = p_envelope_id;

  return v_status;
end;
$$;

