returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_envelope_status text;
  v_count integer;
  v_signed integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select e.status
    into v_envelope_status
    from public.envelopes e
   where e.id = p_envelope_id
   for update;

  if not found then
    raise exception 'envelope not found';
  elsif v_envelope_status <> 'sent' then
    raise exception 'envelope is not open for signing';
  elsif exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.user_id = v_uid
  ) then
    raise exception 'already signed';
  elsif exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.sign_order < (
         select r2.sign_order
           from public.envelope_recipients r2
          where r2.envelope_id = p_envelope_id
            and r2.user_id = v_uid
       )
       and r2.signed_at is null
  ) then
    raise exception 'earlier signer has not signed';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_uid;

  select count(*)::integer
    into v_count
    from public.envelope_recipients
   where envelope_id = p_envelope_id;

  select count(*)::integer
    into v_signed
    from public.envelope_recipients
   where envelope_id = p_envelope_id
     and signed_at is not null;

  if v_signed >= v_count then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;
    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$;

