create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  perform 1
  from public.envelopes e
  where e.id = p_envelope_id
    and e.status = 'sent';

  if not found then
    raise exception 'envelope % is not in sent status', p_envelope_id;
  end if;

  if exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.user_id = v_uid
  ) then
    raise exception 'user % has already signed envelope %', v_uid, p_envelope_id;
  end if;

  if exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.sign_order < (
        select r2.sign_order
        from public.envelope_recipients r2
        where r2.envelope_id = p_envelope_id
          and r2.user_id = v_uid
      )
      and r2.signed_at is null
  ) then
    raise exception 'an earlier recipient has not signed yet';
  end if;

  update public.envelope_recipients
  set signed_at = now()
  where envelope_id = p_envelope_id
    and user_id = v_uid;

  select e.status
  into v_status
  from public.envelopes e
  where e.id = p_envelope_id;

  if not exists (
    select 1
    from public.envelope_recipients r
    where r.envelope_id = p_envelope_id
      and r.signed_at is null
  ) then
    update public.envelopes
    set status = 'completed'
    where id = p_envelope_id;
  end if;

  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  perform 1
  from public.envelopes e
  where e.id = p_envelope_id
    and e.sender_id = v_uid
    and e.status = 'sent';

  if not found then
    raise exception 'envelope % cannot be voided', p_envelope_id;
  end if;

  update public.envelopes
  set status = 'voided'
  where id = p_envelope_id;

  select e.status
  into v_status
  from public.envelopes e
  where e.id = p_envelope_id;

  return v_status;
end;
$$;

