create or replace function public.sign_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_envelope public.envelopes%rowtype;
  v_count integer;
  v_signed integer;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select *
    into v_envelope
    from public.envelopes
   where id = p_envelope_id
   for update;

  if not found then
    raise exception 'unknown envelope';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  if v_envelope.sender_id = v_uid then
    raise exception 'senders cannot sign';
  end if;

  if exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.user_id = v_uid
  ) then
    raise exception 'already signed';
  end if;

  if exists (
    select 1
      from public.envelope_recipients r
     where r.envelope_id = p_envelope_id
       and r.sign_order < (
         select r2.sign_order
           from public.envelope_recipients r2
          where r2.envelope_id = p_envelope_id
            and r2.user_id = v_uid
       )
       and r2.signed_at is null
  ) then
    raise exception 'earlier recipient has not signed';
  end if;

  update public.envelope_recipients
     set signed_at = now()
   where envelope_id = p_envelope_id
     and user_id = v_uid;

  select count(*)
    into v_signed
    from public.envelope_recipients
   where envelope_id = p_envelope_id
     and signed_at is not null;

  select count(*)
    into v_count
    from public.envelope_recipients
   where envelope_id = p_envelope_id;

  if v_signed >= v_count then
    update public.envelopes
       set status = 'completed'
     where id = p_envelope_id;

    v_status := 'completed';
  else
    v_status := 'sent';
  end if;

  return v_status;
end;
$$;

create or replace function public.void_envelope(p_envelope_id bigint)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_status text;
  v_envelope public.envelopes%rowtype;
begin
  if v_uid is null then
    raise exception 'not authenticated';
  end if;

  select *
    into v_envelope
    from public.envelopes
   where id = p_envelope_id
   for update;

  if not found then
    raise exception 'unknown envelope';
  end if;

  if v_envelope.sender_id is distinct from v_uid then
    raise exception 'only the sender can void';
  end if;

  if v_envelope.status <> 'sent' then
    raise exception 'envelope is not sent';
  end if;

  update public.envelopes
     set status = 'voided'
   where id = p_envelope_id;

  v_status := 'voided';
  return v_status;
end;
$$;

