  where p.unit_id = p_unit_id
    and p.revoked = false
    and p.valid_until >= current_date
      and p.id <> public.permits.id
$$;

create or replace function public.permits_enforce_update()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_is_admin boolean := public.is_hoa_admin();
  v_is_resident boolean := public.is_resident_of(new.unit_id);
  v_is_active boolean := public.permit_active(new.id);
begin
  if not v_is_admin and not v_is_resident then
    raise exception 'not allowed to update this permit';
  end if;

  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.plate is null then
    raise exception 'only the plate may be changed';
  end if;

  if new.valid_until is distinct from old.valid_until
     or new.revoked is distinct from old.revoked then
    raise exception 'valid_until and revoked cannot be changed';
  end if;

  if v_is_resident then
    if not public.permit_count_active(new.unit_id) then
      raise exception 'no active permits for this unit';
    end if;
  elsif v_is_admin then
    if new.revoked = false then
      raise exception 'only admins may un-revoke';
    end if;
  end if;

  return new;
end;
$$;

create trigger permits_enforce_update
before update on public.permits
for each row execute function public.permits_enforce_update();

