```sql
alter table public.residents enable row level security;
alter table public.hoa_admins enable row level security;
alter table public.permits enable row level security;

-- Helper: is the current user a HOA admin?
create or replace function public.is_hoa_admin()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.hoa_admins
    where user_id = auth.uid()
  );
$$;

-- Helper: count active (non-revoked, not-expired) permits for a unit
create or replace function public.active_permit_count(p_unit_id bigint)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select count(*)::integer from public.permits
  where unit_id = p_unit_id
    and revoked = false
    and valid_until >= current_date;
$$;

-- Helper: is the current user a resident of the given unit?
create or replace function public.is_resident_of(p_unit_id bigint)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.residents
    where unit_id = p_unit_id
      and user_id = auth.uid()
  );
$$;

revoke all on function public.is_hoa_admin() from public;
revoke all on function public.active_permit_count(bigint) from public;
revoke all on function public.is_resident_of(bigint) from public;
grant execute on function public.is_hoa_admin() to authenticated, service_role;
grant execute on function public.active_permit_count(bigint) to authenticated, service_role;
grant execute on function public.is_resident_of(bigint) to authenticated, service_role;

-- R1: residents see their own residence rows and their unit's permits; admins see all permits
create policy "residents_select_own"
  on public.residents
  for select
  to authenticated
  using (user_id = auth.uid());

create policy "permits_select_own_or_admin"
  on public.permits
  for select
  to authenticated
  using (
    public.is_hoa_admin()
    or public.is_resident_of(unit_id)
  );

-- R2: residents may add permits for their unit (capacity < 2 active), never revoked, ≤ 365 days
create policy "permits_insert_resident"
  on public.permits
  for insert
  to authenticated
  with check (
    public.is_resident_of(unit_id)
    and revoked = false
    and valid_until <= current_date + interval '365 days'
    and public.active_permit_count(unit_id) < 2
  );

-- R3: residents may change the plate on their unit's permits; validity/revocation are immutable
create policy "permits_update_resident_plate"
  on public.permits
  for update
  to authenticated
  using (
    public.is_resident_of(unit_id)
    and revoked = false
  )
  with check (
    public.is_resident_of(unit_id)
    and plate is not null
  );

-- R4: HOA admins may revoke any permit; nobody may un-revoke
create policy "permits_update_admin_revoke"
  on public.permits
  for update
  to authenticated
  using (public.is_hoa_admin())
  with check (
    public.is_hoa_admin()
    and revoked = true
  );

-- R4: permits are never deleted
create policy "permits_no_delete"
  on public.permits
  for delete
  to authenticated
  using (false);

-- R5 / R6: table privileges
revoke all on public.residents from anon;
revoke all on public.hoa_admins from anon;
revoke all on public.permits from anon;

grant select on public.residents to authenticated;
grant select on public.permits to authenticated;
grant insert, update on public.permits to authenticated;
grant usage on sequence public.permits_id_seq to authenticated;
